import json, os, re, zipfile

def run(**kwargs):
    apk_dir = kwargs.get("apk_dir", "missions/playformto.com/apk")
    min_len = int(kwargs.get("min_len", 24))
    max_len = int(kwargs.get("max_len", 64))
    out = {"candidates": [], "scanned": []}
    # regex: base64url charset runs
    rx = re.compile(rb"[A-Za-z0-9_\-]{%d,%d}" % (min_len, max_len))
    seen = set()
    base_apk = os.path.join(apk_dir, "base.apk")
    xapk = os.path.join(apk_dir, "lplayer.xapk")
    targets = []
    if os.path.exists(base_apk):
        z = zipfile.ZipFile(base_apk)
        for n in z.namelist():
            if n.endswith(".dex"):
                targets.append(("base.apk!" + n, z.read(n)))
        z.close()
    if os.path.exists(xapk):
        zx = zipfile.ZipFile(xapk)
        for n in zx.namelist():
            if n.startswith("config.") and n.endswith(".apk"):
                try:
                    inner = zipfile.ZipFile(io.BytesIO(zx.read(n))) if False else None
                except Exception:
                    pass
        # scan .so inside config apks
        import io as _io
        for n in zx.namelist():
            if n.startswith("config.") and n.endswith(".apk"):
                try:
                    zi = zipfile.ZipFile(_io.BytesIO(zx.read(n)))
                    for m in zi.namelist():
                        if m.endswith(".so"):
                            targets.append((n + "!" + m, zi.read(m)))
                    zi.close()
                except Exception:
                    continue
        zx.close()
    for label, data in targets:
        out["scanned"].append(label)
        for m in rx.finditer(data):
            s = m.group().decode()
            if s in seen:
                continue
            # filter: pure hex or pure alpha words are noise; keep mixed-case alnum with digits
            if not re.search(r"[0-9]", s):
                continue
            if not re.search(r"[a-z]", s) or not re.search(r"[A-Z]", s):
                continue
            if re.match(r"^[0-9]+$", s):
                continue
            seen.add(s)
            out["candidates"].append({"len": len(s), "value": s, "src": label})
    out["candidate_count"] = len(out["candidates"])
    return json.dumps(out, ensure_ascii=False)

