    ivs = kwargs.get("ivs", ["2Xk4dLo38c9Z2Q2a"])
    def b64u(s):
        s = s.replace("-", "+").replace("_", "/")
        while len(s) % 4:
            s += "="
        return base64.b64decode(s)
    def unpad(p):
        if not p:
            return p
        n = p[-1]
        if 1 <= n <= 16 and p[-n:] == bytes([n])*n:
            return p[:-n]
        return p
    results = []
    for kc in keys:
        for iv_s in ivs:
            try:
                enc = kc.get("encoding", "raw")
