def run(**kwargs):
    apk_dir = kwargs.get("apk_dir", "missions/playformto.com/apk")
    base_apk = os.path.join(apk_dir, "base.apk")
    z = zipfile.ZipFile(base_apk)
    app_dexes = [n for n in z.namelist() if re.match(r"^classes\d*\.dex$", n)]
    out = {"obf_paths": [], "v1_paths": [], "secretkey_neighbors": [], "app_strings": []}
    # obfuscated word paths like polyphore/fourths/redecimate
    rx_obf = re.compile(rb"/[a-z]{6,12}/[a-z]{4,10}/[a-z]{6,12}")
    rx_v1 = re.compile(rb"/v[12]/[a-z0-9_/]{3,60}")
    seen = set()
    for n in app_dexes:
        data = z.read(n)
        for m in rx_obf.finditer(data):
            s = m.group().decode()
            if s not in seen:
                seen.add(s)
                out["obf_paths"].append(s)
        for m in rx_v1.finditer(data):
            s = m.group().decode()
            if s not in seen:
                seen.add(s)
                out["v1_paths"].append(s)
    # app's own strings: search for iplayer package refs and interesting keys
    for n in app_dexes:
        data = z.read(n)
        for pat in (b"secretKey", b"download_file", b"file_url", b"play_video", b"app_open"):
            idx = 0
            while True:
                i = data.find(pat, idx)
                if i < 0:
                    break
                # extract the surrounding string-pool entries (null-separated)
                s = max(0, i - 300)
                e = min(len(data), i + 300)
                chunk = data[s:e].decode("utf-8", "replace")
                out["secretkey_neighbors"].append({"dex": n, "pat": pat.decode(), "ctx": chunk})
                idx = i + len(pat)
                if len(out["secretkey_neighbors"]) > 12:
                    break
    return json.dumps({k: (v if not isinstance(v, list) else v[:60]) for k, v in out.items()}, ensure_ascii=False)

