    data = json.dumps(body).encode()
    req = Request(url, data=data, headers={"Content-Type": "application/json", "User-Agent": "Mozilla/5.0"})
    raw = urlopen(req, timeout=60).read()
    text = raw.decode("utf-8", "replace")
    out = {"size": len(text)}
    if head_n:
        out["head"] = text[:head_n]
    out["tail"] = text[-tail_n:]
    # also: extract top-level keys and any secretKey-like fields
    try:
        j = json.loads(text)
        out["top_keys"] = list(j.keys()) if isinstance(j, dict) else "list"
        def walk(o, path=""):
            if isinstance(o, dict):
                for k, v in o.items():
                    p = path + "." + k if path else k
                    if any(s in k.lower() for s in ("secret", "key", "token", "config", "user")):
                        out.setdefault("interesting", []).append({"path": p, "value": str(v)[:300]})
                    if isinstance(v, (dict, list)) and len(out.get("interesting", [])) < 40:
                        walk(v, p)
            elif isinstance(o, list):
                for i, v in enumerate(o[:3]):
                    walk(v, path + "[%d]" % i)
        walk(j)
