import io, json, os, re, zipfile

def run(**kwargs):
    apk_dir = kwargs.get("apk_dir", "missions/playformto.com/apk")
    xapk = os.path.join(apk_dir, "lplayer.xapk")
    zx = zipfile.ZipFile(xapk)
    out = {"libs": [], "candidates": []}
    seen = set()
    # b64url 43-44 chars = 32 bytes; also 22-24 (16B) and 31-32 (24B) for completeness
    rx = re.compile(rb"[A-Za-z0-9_\-]{42,46}")
    for n in zx.namelist():
        if not (n.startswith("config.") and n.endswith(".apk")):
            continue
        try:
            zi = zipfile.ZipFile(io.BytesIO(zx.read(n)))
        except Exception:
            continue
        for m in zi.namelist():
            if m.endswith(".so"):
                data = zi.read(m)
                out["libs"].append(n + "!" + m + " (%d bytes)" % len(data))
                if "libapp.so" not in m:
                    continue
                for hit in rx.finditer(data):
                    s = hit.group().decode()
                    if s in seen:
                        continue
                    seen.add(s)
                    # must look like a key: mixed case + digits
                    if not (re.search(r"[0-9]", s) and re.search(r"[a-z]", s) and re.search(r"[A-Z]", s)):
                        continue
                    # skip obvious words
                    if re.match(r"^[a-zA-Z]+$", s):
                        continue
                    ctx_s = max(0, hit.start() - 80)
                    ctx_e = min(len(data), hit.end() + 80)
                    out["candidates"].append({"value": s, "len": len(s), "ctx": data[ctx_s:ctx_e].decode("utf-8", "replace")})
    out["candidate_count"] = len(out["candidates"])
    return json.dumps(out, ensure_ascii=False)

