import json, os, re, zipfile

def run(**kwargs):
    apk_dir = kwargs.get("apk_dir", "missions/playformto.com/apk")
    base_apk = os.path.join(apk_dir, "base.apk")
    z = zipfile.ZipFile(base_apk)
    app_dexes = [n for n in z.namelist() if re.match(r"^classes\d*\.dex$", n)]
    out = {"c43": [], "c32": [], "c44": []}
    seen = set()
    rx43 = re.compile(rb"[A-Za-z0-9_\-]{43}")
    rx44 = re.compile(rb"[A-Za-z0-9_\-]{44}")
    rx32 = re.compile(rb"[A-Za-z0-9]{32}")
    for n in app_dexes:
        data = z.read(n)
        for rx, bucket in ((rx43, "c43"), (rx44, "c44"), (rx32, "c32")):
            for m in rx.finditer(data):
                s = m.group().decode()
                if s in seen:
                    continue
                seen.add(s)
                # skip pure-alpha dictionary words and obvious SDK patterns
                if re.match(r"^[a-z]+$", s) or re.match(r"^[A-Z]+$", s):
                    continue
                if s.lower() in ("abcdefghijklmnopqrstuvwxyz0123456789",):
                    continue
                out[bucket].append({"v": s, "dex": n})
    out["counts"] = {k: len(v) for k, v in out.items() if isinstance(v, list)}
    # cap output
    out["c43"] = out["c43"][:80]
    out["c44"] = out["c44"][:80]
    out["c32"] = out["c32"][:120]
    return json.dumps(out, ensure_ascii=False)

