import base64, json, os, re, zipfile

def run(**kwargs):
    from Crypto.Cipher import AES
    apk_dir = kwargs.get("apk_dir", "missions/playformto.com/apk")
    ct_b64 = kwargs["ciphertext_b64"]
    base_apk = os.path.join(apk_dir, "base.apk")
    z = zipfile.ZipFile(base_apk)
    app_dexes = [n for n in z.namelist() if re.match(r"^classes\d*\.dex$", n)]
    def b64u(s):
        s2 = s.replace("-", "+").replace("_", "/")
        while len(s2) % 4:
            s2 += "="
        try:
            return base64.b64decode(s2)
        except Exception:
            return None
    ct = b64u(ct_b64)
    if ct is None or len(ct) % 16 != 0:
        return json.dumps({"error": "bad ct"})
    # collect candidates: 43-44 char b64url (32B), 22-24 (16B), 31-32 (24B)
    rx = re.compile(rb"[A-Za-z0-9_\-]{22,44}")
    seen = set()
    cands = []
    for n in app_dexes:
        data = z.read(n)
        for m in rx.finditer(data):
            s = m.group().decode()
            if s in seen:
                continue
            seen.add(s)
            # heuristic: must contain digit + lower + upper, not a dictionary word run
            if not (re.search(r"[0-9]", s) and re.search(r"[a-z]", s) and re.search(r"[A-Z]", s)):
                continue
            if re.match(r"^[a-zA-Z]+$", s):
                continue
            kb = b64u(s)
            if kb and len(kb) in (16, 24, 32):
                cands.append((s, kb))
    out = {"candidates_tried": len(cands), "hits": []}
    for s, kb in cands:
        try:
            pt = AES.new(kb, AES.MODE_ECB).decrypt(ct)
            # check for URL signature
            if b"http" in pt or b"%s" in pt or (sum(1 for b in pt if 32 <= b < 127) / len(pt)) > 0.9:
                out["hits"].append({"key": s, "keylen": len(kb), "pt": pt.decode("utf-8", "replace")[:400]})
        except Exception:
            continue
    return json.dumps(out, ensure_ascii=False)

